/// <summary>
/// runBaseBatch class for deleting old internal quotation journals
/// </summary>
public class AVACleanUpQuotationVersion extends RunbaseBatch
{
    int             lastVersion = 3;        // PBI states that anything older than last three versions gets deleted
    QueryRun        queryrun;

    #define.CurrentVersion(1)
    #define.Version1(1)
    #localmacro.CurrentList
        lastVersion
    #endmacro

}

Method.Source:
/// <summary>
/// main method
/// </summary>
/// <param name = "_args">Args</param>
public static void main(Args _args)
{
    AVACleanUpQuotationVersion cleanUpQuotationVersion = AVACleanUpQuotationVersion::construct();

    if (cleanUpQuotationVersion.prompt())
    {
        cleanUpQuotationVersion.run();
    }
}

/// <summary>
/// run method
/// </summary>
public void run()
{
    #OCCRetryCount
    if (! this.validate())
    {
        throw error("@SYS79625");
    }

    try
    {
        ttsbegin;

        this.clearQuotationVersion();

        ttscommit;

        info("@NDX:NXACleanUpQuotationVersionSuccessful");
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
}

/// <summary>
/// deletes unwanted internal quotation versions
/// </summary>
void clearQuotationVersion()
{
    CustQuotationJour       custQuotationJour;

    QuotationId             curQuotationId;
    int                     tableIdQuotJour = tableNum(custQuotationJour);
    int                     curVersion;
    utcdatetime             cleanUpDateTime;
    ;

    //cleanUpDateTime = DateTimeUtil::getSystemDateTime();

    while(queryrun.next())
    {
        if (queryrun.changed(tableIdQuotJour))
        {
            custQuotationJour = queryrun.get(tableIdQuotJour);

            if (!curQuotationId 
                || curQuotationId != custQuotationJour.KCS_QuotationId)
            {
                curQuotationId = custQuotationJour.KCS_QuotationId;
                curVersion = 0;
            }

            curVersion++;

            //if (curVersion > lastVersion && custQuotationJour.createdDateTime <= cleanUpDateTime)
            if (curVersion > lastVersion)
            {
                ttsbegin;
                custQuotationJour.selectForUpdate(true);
                custQuotationJour.delete();
                ttscommit;
            }
        }
    }
}

/// <summary>
/// initParmDefault method
/// </summary>
public void initParmDefault()
{
    this.initQuery();

    super();
}

/// <summary>
/// initializes QueryRun variable
/// </summary>
void initQuery()
{
    Query   query = new Query(QueryStr(AVACleanUpQuotationVersion));
    ;
    queryrun = new SysQueryRun(query);
}

