/// <summary>
/// Dialog object of class
/// </summary>
/// <returns>Object</returns>
public Object dialog()
{
    DialogRunbase   dialog;

    dialog = super();
    dialog.caption("@NDX:NXACleanUpQuotationVersion");

    return dialog;
}

/// <summary>
/// class description string
/// </summary>
/// <returns>ClassDescription</returns>
static ClassDescription description()
{
    return "@NDX:NXACleanUpQuotationVersionDesc";
}

/// <summary>
/// pack method
/// </summary>
/// <returns>container</returns>
public container pack()
{
    return [#CurrentVersion,#CurrentList,queryrun.pack()];
}

/// <summary>
/// unpack method
/// </summary>
/// <returns>container</returns>
public boolean unpack(container packedClass)
{
    Version     version = RunBase::getVersion(packedClass);
    container   queryCon;

    switch (version)
    {
        case #CurrentVersion:
            [version,#CurrentList,queryCon] = packedClass;
            if (SysQuery::isPackedOk(queryCon))
            queryrun = new QueryRun(queryCon);
            else
            this.initQuery();
            break;
        default:
            return false;
    }

    return true;
}

/// <summary>
/// construct method
/// </summary>
/// <returns>AVACleanUpQuotationVersion</returns>
public static AVACleanUpQuotationVersion construct()
{
    return new AVACleanUpQuotationVersion();
}

/// <summary>
/// validate method
/// </summary>
/// <param name = "calledFrom">Object</param>
/// <returns>boolean</returns>
public boolean validate(Object calledFrom = null)
{
    if (lastVersion < 0)
    {
        return checkFailed(strFmt("@NDX:NXACleanUpQuotationValidateError", lastVersion));
    }

    return true;
}
